        "content":  "\u003cp class=\"wp-block-paragraph\"\u003e\u003cem\u003eVİRGİNİA WOOLF\u003c/em\u003e\u003cbr\u003e\u003cbr\u003e\u003c/p\u003e\n\n\n\n\u003cdiv data-wp-interactive=\"core/file\" class=\"wp-block-file\"\u003e\u003cobject data-wp-bind--hidden=\"!state.hasPdfPreview\" hidden class=\"wp-block-file__embed\" data=\"https://bejingmedya.com/wp-content/uploads/2026/06/Virginia-Woolf-Kendine-Ait-Bir-Oda.pdf\" type=\"application/pdf\" style=\"width:100%;height:710px\" aria-label=\"PDF gömme\"\u003e\u003c/object\u003e\u003ca href=\"https://bejingmedya.com/wp-content/uploads/2026/06/Virginia-Woolf-Kendine-Ait-Bir-Oda.pdf\" class=\"wp-block-file__button wp-element-button\" download\u003eİndir\u003c/a\u003e\u003c/div\u003e",
